// Python/JS parity on edge cases generated by pipeline/tests/make_parity_fixture.py (review-01).
// pytest asserts the fixture matches the Python reference; this file runs the same inputs through the JS port.
import { readFileSync } from 'node:fs'
import { basename, resolve } from 'node:path'
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import cases from '../../../pipeline/tests/fixtures/parity_cases.json'
import { loadGrid } from '../data'
import { boundedFraction, cellId, flagMatch, gaussian, geometricMean, greedyPortfolio, ordinalClass, ratioSim, totalScore } from './normalize'

const TOL = 1e-12
const close = (a: number, b: number, what: unknown) => expect(Math.abs(a - b), JSON.stringify(what)).toBeLessThanOrEqual(TOL)

describe('Python/JS parity: scalar scorer edge cases', () => {
  it('ratioSim', () => cases.ratio_sim.forEach((c) => close(ratioSim(c.x, c.t), c.expected, c)))
  it('boundedFraction', () => cases.bounded_fraction.forEach((c) => close(boundedFraction(c.x, c.t), c.expected, c)))
  it('gaussian', () => cases.gaussian.forEach((c) => close(gaussian(c.x, c.t, c.tau), c.expected, c)))
  it('ordinalClass', () => cases.ordinal_class.forEach((c) => close(ordinalClass(c.x, c.t, c.n_classes), c.expected, c)))
  it('flagMatch', () => cases.flag_match.forEach((c) => close(flagMatch(c.earth, c.target), c.expected, c)))
  it('geometricMean (zeros, zero weights, all-zero weights, floors)', () =>
    cases.geometric_mean.forEach((c) =>
      close(geometricMean(c.scores as Record<string, number>, c.weights as Record<string, number>, c.floor), c.expected, c)))
  it('totalScore', () => cases.total_score.forEach((c) => close(totalScore(c.core, c.secondary as number[]), c.expected, c)))
  it('cellId (poles, antimeridian, wraps, cell edges)', () =>
    cases.cell_id.forEach((c) => expect(cellId(c.lat, c.lon), JSON.stringify(c)).toBe(c.expected)))
  it('greedyPortfolio (ties, duplicates, lambda, caps)', () =>
    cases.set_cover.forEach((c) =>
      expect(
        greedyPortfolio(c.sites as never, c.weights as Record<string, number>, c.theta, c.lam, c.max_sites).map((s) => s.site_id),
        JSON.stringify({ w: c.weights, theta: c.theta, lam: c.lam }),
      ).toEqual(c.expected_ids)))
})

describe('Python/JS parity: binary grid decode (loadGrid vs read_grid)', () => {
  const fixtures = resolve(__dirname, '../../../pipeline/tests/fixtures')
  beforeAll(() => {
    vi.stubGlobal('fetch', async (u: string) => {
      const b = readFileSync(resolve(fixtures, basename(u)))
      const ab = b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength)
      return { ok: true, status: 200, json: async () => JSON.parse(b.toString('utf8')), arrayBuffer: async () => ab }
    })
  })
  afterAll(() => vi.unstubAllGlobals())

  it('decodes every column, nodata -> NaN, within float32 precision', async () => {
    const { manifest, columns } = await loadGrid(cases.grid.manifest)
    expect(manifest.byte_order).toBe('little')
    const expected = cases.grid.expected as Record<string, (number | null)[]>
    expect(Object.keys(columns)).toEqual(Object.keys(expected))
    for (const [name, want] of Object.entries(expected)) {
      want.forEach((w, i) => {
        const got = columns[name][i]
        if (w === null) expect(Number.isNaN(got), `${name}[${i}] should be NaN`).toBe(true)
        else expect(Math.abs(got - w), `${name}[${i}]: ${got} vs ${w}`).toBeLessThanOrEqual(Math.abs(w) * 2 ** -23)
      })
    }
  })
})
